package com.rentalproperty.servlet;
import com.rentalproperty.util.DBConnection; import javax.servlet.*; import javax.servlet.annotation.WebServlet; import javax.servlet.http.*; import java.io.*; import java.sql.*; import java.time.LocalDate;
@WebServlet("/rentalRequest") public class RentalRequestServlet extends HttpServlet {
 protected void doPost(HttpServletRequest req,HttpServletResponse res)throws ServletException,IOException{HttpSession s=req.getSession(false);if(s==null||s.getAttribute("userId")==null){res.sendRedirect("login.jsp");return;}try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement("INSERT INTO rental_requests(property_id,tenant_id,tenant_name,phone,message,request_date) VALUES(?,?,?,?,?,?)")){p.setInt(1,Integer.parseInt(req.getParameter("propertyId")));p.setInt(2,(Integer)s.getAttribute("userId"));p.setString(3,req.getParameter("tenantName"));p.setString(4,req.getParameter("phone"));p.setString(5,req.getParameter("message"));p.setDate(6,Date.valueOf(LocalDate.now()));p.executeUpdate();res.sendRedirect("properties?msg=requested");}catch(Exception e){throw new ServletException(e);}}
}
